<?php
require_once __DIR__ . '/_layout.php';requirePermission('reservations.manage');if(requestMethod()==='POST'){requireCsrfPost();try{$request=dbFetchOne('SELECT cr.*,c.agency_id FROM customer_requests cr JOIN customers c ON c.id=cr.customer_id WHERE cr.id=:id FOR UPDATE',['id'=>(int)($_POST['id']??0)]);if(!$request)throw new InvalidArgumentException('Request not found.');requireAgencyAccess($request['agency_id']);$decision=validateChoice($_POST['decision']??'',['approved','rejected'],'');if(!$decision)throw new InvalidArgumentException('Select a decision.');if($decision==='approved'&&$request['request_type']==='cancellation_request'&&$request['reservation_id'])transitionReservation($request['reservation_id'],'cancelled','Approved customer portal request');dbExecute('UPDATE customer_requests SET status=:status,resolution_notes=:notes,resolved_at=NOW(),resolved_by=:user WHERE id=:id',['status'=>$decision,'notes'=>trim((string)($_POST['notes']??'')),'user'=>currentUserId(),'id'=>$request['id']]);auditLog('customer_request.resolved','customer_request',$request['id'],['status'=>$request['status']],['status'=>$decision],$request['agency_id']);flash('success','Customer request resolved.');}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Customer request resolution failed');flash('danger','The request could not be resolved.');}safeRedirect('requests.php');}$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$requests=dbFetchAll("SELECT cr.*,c.first_name,c.last_name,r.reference FROM customer_requests cr JOIN customers c ON c.id=cr.customer_id LEFT JOIN reservations r ON r.id=cr.reservation_id WHERE c.agency_id IN ($ph) ORDER BY FIELD(cr.status,'pending','approved','rejected'),cr.created_at DESC",$ids);backofficeHeader('Portal requests','requests.php');?><div class="page-head"><h1>Customer portal requests</h1></div><div class="table-wrap"><table><tr><th>Created</th><th>Customer</th><th>Reservation</th><th>Type</th><th>Message</th><th>Status</th><th>Decision</th></tr><?php foreach($requests as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['reference'])?></td><td><?=e($r['request_type'])?></td><td style="white-space:normal"><?=e($r['message'])?></td><td><?=statusBadge($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=e($r['id'])?>"><select name="decision"><option>approved</option><option>rejected</option></select><input name="notes" placeholder="Resolution notes"><button class="btn primary">Resolve</button></form><?php else:?><?=e($r['resolution_notes'])?><?php endif;?></td></tr><?php endforeach;?></table></div><?php backofficeFooter();
